// Datos reales de guantes de arquero de fútbol.
//
// Primera carga (2026-09-17, pedido explícito del usuario tras el
// trabajo de botas: "el resto del catálogo... buscar en todo el
// catálogo los nuevos productos"): minados de los mismos feeds Awin ya
// aprobados para camisetas/botas (/tmp/feeds/*.csv del scan diario) --
// ver scripts/gear-mining/mine_gear.py. Todas las tiendas cobran en EUR,
// así que no hace falta el patrón multi-moneda de boots.ts/products.ts
// (formatOfferMoney de @/lib/offerMoney ya acepta "EUR" directo).
//
// Filtro real por tienda: Foot-Store/Sport is Good (ES y FR) usan su
// taxonomía real "Football > Gants de gardien > Adulte > ..."; Gigasport
// usa "Torwarthandschuhe"/"Gants de gardien de but"; Deporte Outlet no
// tiene categoría confiable, filtro por título ("guantes"+"portero") más
// su propio custom_2 de género para excluir infantil. Precio/talles/URL
// de afiliado/imagen: 100% reales del feed, sin inventar nada.
export interface GloveOffer {
  store:
    | "FootStoreES"
    | "SportIsGoodES"
    | "FootStoreFR"
    | "SportIsGoodFR"
    | "DeporteOutlet"
    | "GigasportDE"
    | "GigasportCH"
    | "GigasportFR";
  price: number;
  // Precio real de la talla más barata del colorway -- mismo motivo que
  // BootOffer.priceMax, algunas tiendas cobran distinto según talla del
  // mismo modelo/color real.
  priceMax?: number;
  shipping: number;
  currency: "EUR";
  url: string;
  imageUrl: string;
  sizes: string[];
  sizePrices?: { size: string; price: number; url: string }[];
}

export interface GloveProduct {
  id: string;
  brand: string;
  model: string;
  offers: GloveOffer[];
}

